"use strict";(globalThis.webpackChunkgrc||=[]).push([[34549],{96120(e){e.exports=JSON.parse('{"citeKey":"leutenegger1997limitationscycle","slug":"leutenegger-1997-limitations-cycle-e48e","title":"Limitations of Cycle Stealing of Parallel Processing on a Network of Homogeneous Workstations","authors":["S. T. Leutenegger","X.-H. Sun"],"venue":"Journal of Parallel and Distributed Computing, Vol.43, No. 3, pp.169-178","type":"Journal","entryType":"article","date":"January, 1997","year":1997,"era":"archive","month":1,"doi":"10.1006/jpdc.1997.1341","abstract":"The low cost and availability of clusters of workstations have lead researchers to re-explore distributed computing using inde- pendent workstations. This approach may provide better cost/ performance than tightly coupled multiprocessors. In practice, this approach often utilizes wasted cycles to run parallel jobs. In this paper we address the feasibility and limitation of such a nondedicated parallel processing environment assuming worksta- tion processes have priority over parallel tasks. We develop a sim- ple analytical model to predict parallel job response times. Our model provides insight into how significantly workstation owner interference degrades parallel program performance. It forms a foundation for task partitioning and scheduling in a nondedicated network environment. A new term, task ratio, which relates the parallel task demand to the mean service demand of nonparallel workstation processes, is introduced. We propose that task ra- tio is a useful metric for determining how a parallel applications should be partitioned and scheduled in order to make efficient use of a nondedicated distributed system.","hasAbstract":true,"lede":"We address the feasibility and limitation of such a nondedicated parallel processing environment assuming worksta- tion processes have priority over parallel tasks.","links":{"pdf":"https://grc.iit.edu/papers/1997/leutenegger-1997-limitations-cycle-e48e.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);